-- Exact catalog/wiki mapping only. Unverified internal records keep a neutral
-- category symbol; do not guess a model from words such as 'rifle' or 'spear'.
function menu.icon_name(category, name)
    if type(name)=='table' then
        name=name.name
    end
    local typed=menu.type_icons and menu.type_icons[category .. ':' .. tostring(name or '')]
    if typed and menu.icons[typed] then return typed end
    local found=menu.wiki_icons and menu.wiki_icons[category .. ':' .. tostring(name or '')]
    if found and menu.icons[found] then return found end
    if category=='weapon' then return 'unknown_weapon' end
    return menu.icons[category] and category or 'unknown_weapon'
end

function menu.readable_number(value)
    if type(value) ~= 'number' then return tostring(value or '-') end
    if value ~= value or math.abs(value) >= 1e12 then return string.format('%.6g',value) end
    local raw = value == math.floor(value) and string.format('%.0f',value) or string.format('%.8g',value)
    local sign, whole, rest = raw:match('^([%-]?)(%d+)(.*)$')
    if not whole or rest:find('[eE]') then return raw end
    whole = whole:reverse():gsub('(%d%d%d)','%1,'):reverse():gsub('^,','')
    return sign .. whole .. rest
end

-- UI POINTER RECENTER FILTER: no new native calls or changes to input blocking.
-- Windows does not identify synthetic motion here. Only treat a large jump from
-- the outer 10% into a small central box as a reset. Ordinary motion stays 1:1.
function menu.pointer_position(window, cx, cy, cw, ch, reset)
    local p = menu.pointer
    if reset or not p or p.window ~= window or p.cw ~= cw or p.ch ~= ch then
        p = { window = window, cw = cw, ch = ch, x = cx, y = cy, px = cx, py = cy }
        menu.pointer, menu.mouse_used = p, false
    else
        local dx, dy = cx - p.px, cy - p.py
        local edge = p.px <= cw * .1 or p.px >= cw * .9 or p.py <= ch * .1 or p.py >= ch * .9
        local center = math.abs(cx - cw / 2) <= 8 and math.abs(cy - ch / 2) <= 8
        local warp = menu.mouse_used and edge and center and (math.abs(dx) >= cw * .35 or math.abs(dy) >= ch * .35)
        if warp then
            if not p.relative then log('menu: UI cursor recenter filtered') end
            p.relative = true
        else
            if dx ~= 0 or dy ~= 0 then menu.mouse_used = true end
            if p.relative then p.x, p.y = p.x + dx, p.y + dy
            else p.x, p.y = cx, cy end
        end
        p.px, p.py = cx, cy
    end
    p.x, p.y = math.max(0, math.min(cw - 1, p.x)), math.max(0, math.min(ch - 1, p.y))
    return p.x, p.y
end

local function menu_draw(now)
    local S, gui = menu.S, menu.gui
    local reset_pointer = menu.width == nil
    do
        menu.width, menu.height = 1920, 1080
        menu_step('Application.back_buffer_size()')
        local ok, w, h = pcall(S.Application.back_buffer_size)
        if ok and type(w) == 'number' and type(h) == 'number' and w >= 640 and h >= 360 then
            menu.width, menu.height = w, h
        end
        log('menu: screen ' .. tostring(menu.width) .. ' x ' .. tostring(menu.height))
    end
    local width, height = menu.width, menu.height
    local scale = math.min(height / 1080, (width - 32) / 1820)
    menu_step('Gui.rect / Gui.text (first frame)')
    local PANEL_W, PANEL_H = 1820, 930
    local left, bottom = (width - PANEL_W * scale) / 2, (height - PANEL_H * scale) / 2
    -- panel coordinates: x from the left edge, y from the TOP edge of the panel (the Gui's origin is bottom left)
    local layers = menu.layers
    local font, material = menu.font, menu.font
    if menu.lang == 'zh' and menu.zh_font then
        font, material = menu.zh_font.font, menu.zh_font.material
        menu_step('Gui.text with the font ' .. font .. ' and the material ' .. material)
    end
    -- layer 900: the panel, 901: bars on it, 902: text
    local function rect(x, y, w_, h_, a, r, g, b, layer)
        if not layers then return end
        S.Gui.rect(gui, S.Vector3(left + x * scale, bottom + (PANEL_H - y - h_) * scale, layer or 901),
                   S.Vector2(w_ * scale, h_ * scale), S.Color(a, r, g, b))
    end
    local function text(str, x, y, size, a, r, g, b)
        local px, py = left + x * scale, bottom + (PANEL_H - y - size) * scale
        S.Gui.text(gui, str, font, size * scale, material,
                   layers and S.Vector3(px, py, 902) or S.Vector2(px, py), S.Color(a, r, g, b))
    end
    local function gray(str, x, y, size) text(str, x, y, size or 14, 255, 210, 210, 210) end
    local function yellow(str, x, y, size) text(str, x, y, size or 14, 255, 255, 214, 0) end
    local function icon(name,x,y,w,h,dark,bright)
        if not layers then return end
        local art=menu.icons[name] or menu.icons.unknown_weapon
        local k=math.min(w/art.w,h/art.h)
        local ox,oy=x+(w-art.w*k)/2,y+(h-art.h*k)/2
        local r,g,b=210,214,217
        if dark then r,g,b=8,12,16 elseif bright then r,g,b=255,214,0 end
        for _,span in ipairs(art) do
            rect(ox+span[1]*k,oy+span[2]*k,span[3]*k,span[4]*k,255,r,g,b,902)
        end
    end
    -- a row of a list: a bar when it is the selected one, dark text on a bright bar
    -- The mouse. The game hides its pointer, so the menu draws one. Where it is comes from Windows, in
    -- the window's own pixels; the panel is laid out in the back buffer's, x from its left edge and y
    -- from its top edge. It only counts once it has moved: a pointer that never moves is not in use.
    local mouse, hot = nil, {}
    local window = A.game_window()
    if window then
        local ok, cx, cy, cw, ch = pcall(A.mouse, window)
        if ok and type(cx) == 'number' and type(cy) == 'number' and
                type(cw) == 'number' and type(ch) == 'number' and cw > 0 and ch > 0 then
            cx, cy = menu.pointer_position(window, cx, cy, cw, ch, reset_pointer)
            mouse = { x = (cx * width / cw - left) / scale,
                      y = (cy * height / ch - (height - bottom - PANEL_H * scale)) / scale }
        else
            menu.pointer, menu.mouse_used = nil, false
        end
    else
        menu.pointer, menu.mouse_used = nil, false
    end
    -- an area that does something when it is clicked; where two overlap, the one made later counts
    local function area(x, y, w_, h_, action) hot[#hot + 1] = { x, y, w_, h_, action } end
    -- on the pages that are plain lists: a click selects a row, a click on the selected row confirms it
    local function pick(current, n, set)
        return function()
            if current == n then menu.click_accept = true else set(n) end
        end
    end
    local function row(label, x, y, w_, here, focused, cells, on_click)
        if on_click then area(x - 8, y, w_, 24, on_click) end
        if here then rect(x - 8, y, w_, 24, 255, focused and 255 or 70, focused and 214 or 70, focused and 0 or 60) end
        label = menu_clip(label, cells or 60)
        if not layers and here then label = '> ' .. label end
        if focused and layers then text(label, x, y + 3, 17, 255, 0, 0, 0)
        elseif here and not layers then text(label, x, y + 3, 17, 255, 255, 214, 0)
        else text(label, x, y + 3, 17, 255, 255, 255, 255) end
    end

    local key = menu_bound
    -- This screen uses the existing game font and known-safe rect/text calls only.
    -- Fit and wrapping count UTF-8 cells so Chinese and long rebound key names stay inside their panes.
    local function fit(str, x, y, w, size, bright)
        str = tostring(str or '')
        local cells = math.max(1, math.floor(w / (size * 0.62)))
        if menu_cells(str) > cells then str = menu_clip(str, cells - 3) .. '...' end
        if bright then yellow(str, x, y, size) else gray(str, x, y, size) end
    end
    local function wrap(str, x, y, w, size, lines, bright)
        local rest = tostring(str or '')
        local cells = math.max(4, math.floor(w / (size * 0.62)))
        for n = 1, lines do
            if rest == '' then break end
            local line = menu_clip(rest, cells)
            if #line < #rest and n < lines then
                local word = line:match('^(.*)%s+%S*$')
                if word and #word > #line / 2 then line = word end
            end
            if n == lines and #line < #rest then line = menu_clip(rest, cells - 3) .. '...' end
            if bright then yellow(line, x, y, size) else gray(line, x, y, size) end
            rest = rest:sub(#line + 1):gsub('^%s+', '')
            y = y + size + 6
        end
        return y
    end
    local function line(x, y, w) rect(x, y, w, 1, 255, 48, 55, 61) end
    local function outline(x, y, w, h, bright)
        local r,g,b = 48,55,61
        if bright then r,g,b = 255,214,0 end
        rect(x,y,w,1,255,r,g,b); rect(x,y+h-1,w,1,255,r,g,b)
        rect(x,y,1,h,255,r,g,b); rect(x+w-1,y,1,h,255,r,g,b)
    end
    local function action_button(action, label, x, y, w, callback)
        outline(x,y,w,38,false)
        -- Never hard-code a key: settings.txt and the Keys page share this resolver.
        local bound = key(action)
        local kw = math.min(150, math.max(58, menu_cells(bound) * 10 + 16))
        fit(bound,x+10,y+10,kw-12,16,true)
        fit(L(label),x+kw,y+10,w-kw-10,16,false)
        if callback then area(x,y,w,38,callback) end
    end
    rect(0, 0, PANEL_W, PANEL_H, 250, 8, 12, 16, 900)
    outline(0,0,PANEL_W,PANEL_H,false)
    rect(0,0,PANEL_W,4,255,255,214,0)
    text('BYOG',24,22,42,255,255,214,0)
    gray('BALANCE YOUR OWN GAME',170,28,17)
    gray('v' .. MOD.version .. ' / FIELD WORKBENCH / ICONS',170,54,13)
    local x = 610
    for n,page in ipairs(MENU_PAGES) do
        local label = L(page)
        local w = math.max(114, 26 + menu_cells(label) * 11)
        area(x,25,w,42,function() menu.page=n end)
        outline(x,25,w,42,n==menu.page)
        if n==menu.page then
            rect(x+1,26,w-2,40,255,255,214,0)
            if layers then text(label,x+14,36,18,255,8,12,16) else yellow(label,x+14,36,18) end
        else gray(label,x+14,36,18) end
        x=x+w+10
    end
    fit(L('Preset') .. ': ' .. tostring(preset_name or ''),1160,28,405,17,false)
    fit(key('prev_page') .. ' / ' .. key('next_page') .. '  ' .. L('page'),1160,55,405,13,false)
    area(1150,20,420,56,function() menu.page=2 end)
    if menu.mode=='capture' then action_button('back','cancel',1590,26,205)
    else action_button('toggle','close',1590,26,205,function() menu_close(now) end) end
    line(16,90,PANEL_W-32)
    local hints = {}
    local function hint(keys, what) hints[#hints + 1] = { keys, L(what) } end
    local TOP = menu.page == 1 and 220 or 156
    local lists = menu_lists()
    if not lists then
        text(L('reading the built-in data ...'), 20, TOP, 18, 255, 220, 220, 220)
    elseif menu.page == 1 then

        local CAT, LIB, TABLE, INS = 18, 256, 650, 1410
        local searching = menu.filter ~= '' or (menu.box and menu.box.kind == 'search')
        for _, xx in ipairs({238,628,1390}) do rect(xx,106,1,704,255,48,55,61) end
        gray(L('CATEGORIES'),CAT+12,116,16)
        for n,category in ipairs(MENU_CATEGORIES) do
            local y = 153 + (n-1)*43
            local active = n==menu.tab and not searching
            if active then rect(CAT,y,204,36,255,255,214,0) end
            local label = L(MENU_CATEGORY_NAME[category])
            icon(category,CAT+10,y+5,28,26,active,false)
            local tx=CAT+(layers and 48 or 12)
            if active and layers then text(label,tx,y+9,17,255,8,12,16)
            elseif active then yellow(label,tx,y+9,17)
            else gray(label,tx,y+9,17) end
            line(CAT,y+40,204)
            area(CAT,y,204,36,function() menu.tab,menu.filter,menu.focus=n,'','items' end)
        end
        local list, category = menu_current(lists)
        local selected = math.min(menu.item[category] or 1, math.max(#list,1))
        local item = list[selected]
        fit(searching and L('Search') or L(MENU_CATEGORY_NAME[category]),LIB,116,350,23,false)
        local box_y = 161
        outline(LIB,box_y,350,36,menu.box and menu.box.kind=='search')
        local prompt = L('press %s to search'):format(key('search'))
        if menu.box and menu.box.kind=='search' then prompt=L('search') .. ': ' .. menu.box.text .. '_'
        elseif menu.filter~='' then prompt=L('search') .. ': ' .. menu.filter end
        fit(prompt,LIB+10,box_y+10,330,15,searching)
        area(LIB,box_y,350,36,function() menu.focus='items'; menu_box_open('search',menu.filter) end)
        local LIB_ROWS,LIB_STEP=12,44
        local first=math.max(1,math.min(selected-5,#list-LIB_ROWS+1))
        for n=0,LIB_ROWS-1 do
            local entry=list[first+n]
            if entry then
                local y=TOP+n*LIB_STEP
                local here=first+n==selected
                if here then
                    rect(LIB,y,350,42,255,48,45,21)
                    rect(LIB,y,3,42,255,255,214,0)
                    if menu.focus=='items' then outline(LIB,y,350,42,true) end
                end
                local label=entry.display or entry.name
                if searching then label='[' .. MENU_CATEGORY_TAG[entry.category] .. '] ' .. label end
                icon(menu.icon_name(entry.category,entry),LIB+12,y+8,64,26,false,here)
                local inset=layers and 88 or 12
                label=(not layers and here and '> ' or '') .. label
                local room=350-inset-10
                local label_y=menu_cells(label)*15*.62>room and y+4 or y+13
                wrap(label,LIB+inset,label_y,room,15,2,here)
                line(LIB,y+43,350)
                area(LIB,y,350,42,function() menu.item[category],menu.focus=first+n,'items' end)
            end
        end
        local under=TOP+MENU_ROWS*30+12
        gray(string.format('%d %s %d',#list>0 and selected or 0,L('of'),#list),LIB,under,14)
        if not item then
            gray(L('No matching items'),TABLE,TOP,20)
        else
            fit(item.display or item.name,TABLE,114,720,26,false)
            fit(item.name,TABLE,149,720,14,false)
            gray(L('PARAMETER'),TABLE+8,190,14)
            gray(L('value'),TABLE+365,190,14)
            gray(L('game'),TABLE+490,190,14)
            gray(L('CHANGE'),TABLE+620,190,14)
            line(TABLE,211,720)
            local rows,stats=menu_rows(item)
            local at=math.min(menu.stat[item] or 1,#stats)
            local at_row=1
            for index,entry in ipairs(rows) do if entry.n==at then at_row=index end end
            local top=math.max(1,math.min(at_row-8,#rows-MENU_ROWS+1))
            local function edit_value(owner,stat)
                menu.focus='stats'
                menu_box_open('value','',function(typed,at_time)
                    local number=tonumber(typed)
                    if number then menu_set(owner,stat,number,at_time) end
                end)
            end
            for n=0,MENU_ROWS-1 do
                local entry=rows[top+n]
                local y=TOP+n*30
                if entry and entry.heading then
                    local label=(entry.closed and '[+] ' or '[-] ') ..
                        (entry.section and entry.heading:upper() or menu_heading(entry.heading))
                    if not layers and entry.n==at then label='> ' .. label end
                    local inset=(item.members and entry.level==2) and 16 or 0
                    rect(TABLE,y,720,28,255,26,32,36)
                    if entry.n==at then outline(TABLE,y,720,28,menu.focus=='stats') end
                    fit(label,TABLE+8+inset,y+7,700-inset,15,true)
                    area(TABLE,y,720,28,function() menu.focus='stats'; menu.toggle(item,entry.key) end)
                elseif entry and entry.stat then
                    local stat,owner=entry.stat,entry.owner or item
                    local value,changed=menu_value(owner,stat)
                    local field=owner.stats[stat] and owner.stats[stat].field
                    local here=entry.n==at
                    if here then
                        rect(TABLE,y,720,28,255,38,37,24)
                        if menu.focus=='stats' then outline(TABLE,y,720,28,true) end
                    end
                    line(TABLE,y+29,720)
                    fit((not layers and here and '> ' or '') .. menu_label(stat),TABLE+12,y+7,331,16,here)
                    local shown=field and show(value,field.storage) or (value and menu.donor_shown(value) or L('its own'))
                    if stat:find('status%d_type$') and MENU_STATUS[value] then shown=shown .. ' ' .. MENU_STATUS[value] end
                    if here and menu.box and menu.box.kind=='value' then shown='= ' .. menu.box.text .. '_' end
                    fit(shown,TABLE+365,y+7,115,16,changed or (here and menu.mode=='text'))
                    fit(field and show(field.stock,field.storage) or '',TABLE+490,y+7,120,16,false)
                    local delta=field and type(value)=='number' and value-field.stock or nil
                    fit(delta and delta~=0 and string.format('%+.5g',delta) or '-',TABLE+620,y+7,90,16,changed)
                    area(TABLE,y,720,28,function()
                        menu.stat[item],menu.focus=entry.n,'stats'
                        if mouse and mouse.x>=TABLE+355 and mouse.x<TABLE+485 and stat~='blast_from' then
                            edit_value(owner,stat)
                        end
                    end)
                end
            end
            gray(string.format('%d %s %d',at,L('of'),#stats),TABLE,under,14)
            local stat,owner=stats[at],menu.owner(item,at)
            outline(INS,106,390,498,false)
            local iy=124
            gray(L(stat and 'SELECTED PARAMETER' or 'SELECTED GROUP'),INS+16,iy,15)
            line(INS+16,iy+28,358)
            local pick=item.menu_picks and item.menu_picks[at]
            iy=wrap(stat and menu_label(stat) or (pick and menu_heading(pick.heading) or ''),INS+16,168,358,21,2,true)+8
            if stat then
                iy=wrap(stat,INS+16,iy,358,14,2,false)+5
                if item.members then iy=wrap(owner.display or owner.name,INS+16,iy,358,14,2,false)+5 end
                local value,changed=menu_value(owner,stat)
                local field=owner.stats[stat] and owner.stats[stat].field
                if field then
                    gray(L('value'),INS+16,iy,16)
                    fit(show(value,field.storage),INS+190,iy,180,18,changed); iy=iy+29
                    gray(L('game'),INS+16,iy,16)
                    fit(show(field.stock,field.storage),INS+190,iy,180,18,false); iy=iy+29
                    local delta=value-field.stock
                    local change=string.format('%+.5g',delta)
                    if field.stock~=0 then change=change .. string.format(' (%+.1f%%)',delta/math.abs(field.stock)*100) end
                    fit(L('CHANGE') .. ': ' .. change,INS+16,iy,358,16,changed); iy=iy+31
                    local range=RANGES[stat]
                    if range then
                        fit(L('Range') .. ': ' .. tostring(range.min) .. ' ... ' .. tostring(range.max),INS+16,iy,358,14,false)
                        iy=iy+25
                    end
                    if stat:find('status%d_type$') and MENU_STATUS[value] then
                        iy=wrap(MENU_STATUS[value],INS+16,iy,358,14,2,false)
                    elseif owner.hints and owner.hints[stat] then
                        iy=wrap(owner.hints[stat],INS+16,iy,358,14,2,false)
                    end
                    if menu.descriptions[stat] and iy<=428 then
                        wrap(L(menu.descriptions[stat]),INS+16,iy+4,358,14,2,false)
                    end
                    action_button('accept','Enter value',INS+16,474,358,function() edit_value(owner,stat) end)
                else
                    wrap(value and menu.donor_shown(value) or L('its own'),INS+16,iy,358,18,2,true)
                    wrap(key('left') .. ' / ' .. key('right') .. '  ' .. L('change'),INS+16,434,358,16,2,false)
                end
                action_button('reset','reset',INS+16,524,358,function()
                    overrides[menu_key_of(owner,stat)]=nil
                    menu.dirty_at=now
                end)
                local warning=menu_warning(owner,stat)
                if item.category=='status' then warning=warning or L('A status effect has one length: it is the same for every weapon and enemy that applies it') end
                if warning and not menu.note then wrap('! ' .. warning,20,PANEL_H-111,1778,14,2,true) end
            else
                wrap(L('Open this group to inspect its values.'),INS+16,iy+10,358,17,3,false)
                action_button('accept','type / open',INS+16,434,358,function()
                    menu.focus='stats'
                    if pick then menu.toggle(item,pick.key,false) end
                end)
            end
            -- Per-item summary includes hidden sections and grouped members, not just visible rows.
            local changes={}
            for _,member in ipairs(item.members or {item}) do
                local _,all=menu.base_rows(member)
                for _,name in ipairs(all) do
                    if overrides[menu_key_of(member,name)]~=nil then changes[#changes+1]={owner=member,stat=name} end
                end
            end
            local shown = math.min(3,#changes)
            local summary_h = #changes == 0 and 86 or 52 + shown * 42 + (#changes>shown and 20 or 8)
            outline(INS,618,390,summary_h,false)
            gray(L('MODIFIED VALUES'),INS+16,634,15)
            rect(INS+334,628,40,26,255,40,43,30)
            fit(tostring(#changes),INS+345,634,26,15,true)
            for n=1,shown do
                local change=changes[n]
                local y=662+(n-1)*42
                rect(INS+12,y-2,366,39,255,n%2==1 and 18 or 12,24,28)
                local label=menu_label(change.stat)
                if item.members then label=(change.owner.display or change.owner.name) .. ': ' .. label end
                fit(label,INS+20,y,242,14,false)
                local v=menu_value(change.owner,change.stat)
                local f=change.owner.stats[change.stat] and change.owner.stats[change.stat].field
                if f and type(v)=='number' and type(f.stock)=='number' then
                    local delta=v-f.stock
                    fit((delta>=0 and '+' or '') .. menu.readable_number(delta),INS+272,y,98,14,true)
                    fit(menu.readable_number(f.stock) .. ' -> ' .. menu.readable_number(v),INS+20,y+18,350,13,false)
                else
                    fit(menu.donor_shown(v),INS+20,y+18,350,13,true)
                end
            end
            if #changes==0 then gray(L('No changes'),INS+16,666,15)
            elseif #changes>shown then fit('+' .. (#changes-shown) .. ' ' .. L('values'),INS+20,662+shown*42,350,13,false) end
        end
        if menu.mode == 'text' then
            hint(key('accept'), 'confirm'); hint(key('back'), 'cancel'); hint('BACKSPACE', 'delete a letter')
        else
            hint(key('up') .. '/' .. key('down'), 'move'); hint(key('column'), 'lists')
            hint(key('page_up') .. '/' .. key('page_down'), '10 rows')
            hint(key('left') .. '/' .. key('right'), 'change'); hint(key('fast'), 'x10')
            hint(key('reset'), 'reset')
            if menu.focus == 'items' then hint(key('accept') .. '/' .. key('search'), 'search')
            else hint(key('accept'), 'type / open'); hint(key('back'), 'close'); hint(key('search'), 'search') end
        end
    elseif menu.page == 2 then
        gray(L('Presets'),24,116,24)
        local visible = math.floor((PANEL_H - 160 - TOP) / 26)
        local first_preset = math.max(1, math.min(menu.preset_row - 8, #menu.presets + 3 - visible))
        for n, name in ipairs(menu.presets) do
            local here = n == menu.preset_row
            local y = TOP + (n - first_preset) * 26
            if n >= first_preset and n < first_preset + visible then
                local label = name
                if name == preset_name then
                    local count = 0
                    for _ in pairs(overrides) do count = count + 1 end
                    label = name .. '   (' .. L('active') .. ', ' .. count .. ' ' .. L('values') .. ')'
                end
                row(label, 24, y, 620, here, here and menu.mode == 'list', 58,
                    pick(menu.preset_row, n, function(k) menu.preset_row = k end))
                if here then
                    local ax = 660
                    for a, action in ipairs(MENU_PRESET_ACTIONS) do
                        local label_a = L(action)
                        area(ax, y, 24 + menu_cells(label_a) * 10, 24, function()
                            menu.preset_action, menu.click_accept = a, true
                        end)
                        if a == menu.preset_action then yellow('[' .. label_a .. ']', ax, y + 3, 17)
                        else gray(label_a, ax + 6, y + 3, 17) end
                        ax = ax + 30 + menu_cells(label_a) * 10
                    end
                end
            end
        end
        for n, label in ipairs({ '+ New preset (empty)', '+ New preset (copy of the active one)' }) do
            local index = #menu.presets + n
            local y = TOP + (index - first_preset) * 26
            if index >= first_preset and index < first_preset + visible then row(L(label), 24, y, 620, index == menu.preset_row, index == menu.preset_row
                                          and menu.mode == 'list', 58,
                                          pick(menu.preset_row, index, function(k) menu.preset_row = k end)) end
        end
        if menu.box and menu.box.kind == 'name' then
            rect(16, PANEL_H - 104, 520, 24, 255, 255, 214, 0)
            if layers then text(L('Name') .. ': ' .. menu.box.text .. '_', 24, PANEL_H - 101, 17, 255, 0, 0, 0)
            else yellow(L('Name') .. ': ' .. menu.box.text .. '_', 24, PANEL_H - 101, 17) end
        elseif menu.ask then
            yellow(L('Delete the preset "%s"?   %s yes   %s no'):format(menu.ask.name, key('accept'), key('back')), 24,
                   PANEL_H - 101, 17)
        end
        if menu.mode == 'text' then
            hint(key('accept'), 'confirm'); hint(key('back'), 'cancel'); hint('BACKSPACE', 'delete a letter')
        elseif menu.mode == 'confirm' then
            hint(key('accept'), 'confirm'); hint(key('back'), 'cancel')
        else
            hint(key('up') .. '/' .. key('down'), 'move'); hint(key('left') .. '/' .. key('right'), 'action')
            hint(key('accept'), 'select')
        end
    elseif menu.page == 3 then
        gray(L('Keys'),24,116,24)
        local clash = menu_key_clash()
        for n, action in ipairs(MENU_ACTIONS) do
            local here = n == menu.key_row
            local y = TOP + (n - 1) * 26
            row(L(action[3]), 24, y, 760, here, here and menu.mode == 'list', 44,
                pick(menu.key_row, n, function(k) menu.key_row = k end))
            local bound = key(action[1])
            local dark = here and menu.mode == 'list' and layers
            if dark then text(bound, 520, y + 3, 17, 255, 0, 0, 0)
            elseif bound == clash then yellow('! ' .. bound, 520, y + 3, 17)
            else gray(bound, 520, y + 3, 17) end
        end
        local y = TOP + #MENU_ACTIONS * 26
        local n = #MENU_ACTIONS + 1
        local state_text = menu.block_missing and L('not available in this game') or (menu.block and L('on') or L('off'))
        row(L('Block game input while the menu is open'), 24, y, 760, n == menu.key_row, n == menu.key_row
            and menu.mode == 'list', 44, pick(menu.key_row, n, function(k) menu.key_row = k end))
        if n == menu.key_row and menu.mode == 'list' and layers then text(state_text, 520, y + 3, 17, 255, 0, 0, 0)
        else gray(state_text, 520, y + 3, 17) end
        gray(L(menu.block_failed and 'switched off: the game closed when this was tried'
               or 'the game gets no keys and no mouse'), 800, y + 5)
        row(L('Reset the keys'), 24, y + 26, 760, n + 1 == menu.key_row, n + 1 == menu.key_row and menu.mode == 'list', 44,
            pick(menu.key_row, n + 1, function(k) menu.key_row = k end))
        if menu.capture then
            yellow(L('Press the key for: %s   (%s cancels)'):format(L(menu.capture.label), key('back')), 24, PANEL_H - 101, 17)
        end
        if menu.mode == 'capture' then hint(key('back'), 'cancel')
        else hint(key('up') .. '/' .. key('down'), 'move'); hint(key('accept'), 'select') end
    else
        gray(L('Language'),24,116,24)
        local names = { 'English', menu.lang == 'zh' and L('Chinese (Simplified)') or 'Chinese (Simplified)' }
        for n, name in ipairs(names) do
            local here = n == menu.lang_row
            local chosen = (n == 1) == (menu.lang == 'en')
            row(name .. (chosen and '   *' or ''), 24, TOP + (n - 1) * 26, 620, here, here, 58,
                pick(menu.lang_row, n, function(k) menu.lang_row = k end))
        end
        if menu.zh_failed then gray(L('Chinese is switched off: the game stopped when it was drawn'), 660, TOP + 26 + 5)
        elseif not menu.zh_font then gray(L('no font of the game can draw Chinese'), 660, TOP + 26 + 5) end
        hint(key('up') .. '/' .. key('down'), 'move'); hint(key('accept'), 'select')
    end
    if menu.mode~='capture' then hint(key('toggle'), 'close') end
    if menu.note and now and now < (menu.note_until or 0) then
        wrap('! ' .. menu.note,20,PANEL_H-111,1778,14,2,true)
    else
        menu.note = nil
    end

    line(16,PANEL_H-76,PANEL_W-32)
    fit(tostring(state.verdict or ''),20,PANEL_H-66,1300,14,false)
    if menu.dirty_at then fit(L('Pending changes'),1350,PANEL_H-66,445,14,true)
    elseif menu.saved_at then fit(L('Saved to') .. ' "' .. tostring(preset_name) .. '"',1350,PANEL_H-66,445,14,false) end
    local hx,hy=20,PANEL_H-43
    -- Long user-assigned keys get a second line, never silently lose the close/cancel hint.
    for _,h in ipairs(hints) do
        local kw=menu_cells(h[1])*8+14
        local hw=kw+menu_cells(h[2])*8+26
        if hx+hw>PANEL_W-20 then hx,hy=20,hy+21 end
        outline(hx,hy,kw,18,false)
        yellow(h[1],hx+6,hy+2,12)
        gray(h[2],hx+kw+7,hy+2,12)
        hx=hx+hw
    end
    -- the pointer, and what a click does. Only while the lists are in charge: a box that is being typed
    -- into, a key that is being chosen and a question take no clicks.
    local button = A.key_down(0x01)
    if mouse and menu.mouse_used then
        rect(mouse.x - 1, mouse.y - 1, 12, 12, 255, 0, 0, 0, 903)
        rect(mouse.x, mouse.y, 10, 10, 255, 255, 214, 0, 904)
        if button and not menu.mouse_down and menu.mode == 'list' then
            local hit = nil
            for _, h in ipairs(hot) do
                if mouse.x >= h[1] and mouse.x < h[1] + h[3] and mouse.y >= h[2] and mouse.y < h[2] + h[4] then hit = h end
            end
            if hit then hit[5]() end
        end
    end
    menu.mouse_down = button
    if not menu_trail.drawn then
        menu_trail.drawn = true
        log('menu: first frame drawn')
        flush_log()
    end
    if menu.box and not menu_trail['box ' .. menu.box.kind] then
        menu_trail['box ' .. menu.box.kind] = true
        log('menu: the ' .. menu.box.kind .. ' box: first frame drawn')
        flush_log()
    end
    if menu.lang == 'zh' and menu.zh_trying then
        menu.zh_frames = (menu.zh_frames or 0) + 1
        if menu.zh_frames >= 60 then
            menu.zh_trying, menu.lang_saved = nil, 'zh'
            pcall(menu_settings_save)
            log('menu: Chinese drawn for 60 frames: kept')
        end
    end
end

-- once per frame
local function menu_tick()
    if not menu.loaded then pcall(menu_load) end
    local now = A.now()
    if menu.settings_unsaved and now - (menu.settings_tried or 0) > 0.5 then
        menu.settings_tried = now
        pcall(menu_settings_save)
    end
    local down = A.key_down(KEY_VK[menu_bound('toggle')] or config.menu_vk)
    local toggled = down and not menu.toggle_down
    menu.toggle_down = down
    if toggled and not A.game_in_front() then toggled = false end
    -- while a key is being chosen, or a box is typed into, the menu key is a key like any other
    if toggled and menu.open and menu.mode == 'capture' then toggled = false end
    if toggled then
        if menu.open then
            menu_close(now)
        else
            local ok, started, why = pcall(menu_start)
            if ok and started then
                menu.open, menu.state = true, 'open'
            else
                menu.state = 'failed: ' .. tostring(why or started)
                log('menu: ' .. menu.state)
            end
        end
    end
    -- (only ever set while the menu is open)
    if menu.keys_blocked then menu.block_watch(now) end
    if not menu.open then return end
    local ok, why = pcall(function()
        menu_input(now)
        menu_draw(now)
    end)
    if not ok then
        log('menu: closed after an error: ' .. tostring(why))
        menu_close(now)
        menu.state = 'failed: ' .. tostring(why)
    end
end


local function tick()
    state.frame = state.frame + 1
    if state.frame < START_FRAME then return end
    menu_tick()
    -- the reload key: one key-state read per frame; the window is only checked on a press
    local down = A.key_down(config.reload_vk)
    if down and not key_was_down and A.game_in_front() then
        local pressed_at = A.now()
        if pressed_at - last_key_reload >= RELOAD_DEBOUNCE then
            last_key_reload = pressed_at
            log('reload key pressed')
            request_reload()
        end
    end
    key_was_down = down
    if state.frame % STEP_EVERY ~= 0 then return end
    local now = A.now()
    if config.auto_reload > 0 and now >= wake.config_check_at and build.state == 'verified' then
        wake.config_check_at = now + config.auto_reload
        local text = read_file(MOD.config)
        if text ~= nil and text ~= config.text then
            log('config.txt changed on disk')
            request_reload()
        end
    end
    if now < wake.at then return end
    if not worker then worker = coroutine.create(worker_main) end
    deadline = now + FRAME_BUDGET
    local ok, why = coroutine.resume(worker)
    local cost = A.now() - now
    state.busy_frames, state.busy_seconds = state.busy_frames + 1, state.busy_seconds + cost
    if cost > state.worst_frame then state.worst_frame, state.worst_step = cost, tostring(state.step) end
    if not ok then
        state.errors = state.errors + 1
        log('worker failed: ' .. tostring(why))
        worker = nil
        if state.errors >= 5 then
            state.phase, state.failure = 'gave_up', 'too many errors, last: ' .. tostring(why)
            state.retired = true
            write_status(true)
        else
            wake.at = A.now() + 5
            write_status(true)
        end
    end
end

-- ---------------------------------------------------------------- API (for a future UI)
-- Read access to everything the engine knows, and a way to change values without the file.
state.api = {
    version = 1,
    categories = function()
        local seen, list = {}, {}
        for index = 0, #ITEMS do
            local item = ITEMS[index]
            if item and not seen[item.category] then seen[item.category] = true; list[#list + 1] = item.category end
        end
        return list
    end,
    items = function(category)
        local list = {}
        for index = 0, #ITEMS do
            local item = ITEMS[index]
            if item and item.category == category then list[#list + 1] = item.name end
        end
        return list
    end,
    -- -> list of { id, game, current, min, max, integer, editable, shared_with }
    stats = function(category, name)
        local item = ITEM_BY_NAME[tostring(category) .. ':' .. tostring(name):lower()]
        if not item then return nil end
        local list = {}
        for _, stat in ipairs(item.stat_order) do
            local entry, range = item.stats[stat], RANGES[stat]
            local want = desired[entry.field.key]
            list[#list + 1] = { id = stat, game = entry.field.stock, current = want and want.value or entry.field.stock,
                                min = range.min, max = range.max, integer = range.integer,
                                editable = not entry.attachment, shared_with = #entry.field.users - 1 }
        end
        return list
    end,
    -- expression: '120', '150%', '+15', or nil to drop the override
    set = function(category, name, stat, expression)
        overrides[tostring(category):lower() .. ':' .. tostring(name):lower() .. ':' .. tostring(stat):lower()] =
            expression ~= nil and tostring(expression) or nil
        request_reload()
    end,
    reload = request_reload,
    verdict = function() return state.verdict end,
    close_menu = function() if menu.open then menu_close(A.now()) end end,
    hook_code = function(flag, next_hook) return A.hook_code(flag, next_hook) end,
}

-- ---------------------------------------------------------------- startup
log(MOD.title .. ' v' .. MOD.version)
local api_ok, api_failure = pcall(function()
    assert(ffi_ok and ffi, 'LuaJIT FFI is unavailable')
    assert(ffi.abi('64bit'), 'Windows x64 is required')
    A = build_api()
end)
if not api_ok then A = nil end
local ok, failure = pcall(function()
    local loader = rawget(_G, 'CowboyBingusModLoader')
    if type(loader) == 'table' and tonumber(loader.api) and tonumber(loader.api) < 1 then
        error('Bingus Shared Loader is too old (API ' .. tostring(loader.api) .. '); v15 or newer is required', 0)
    end
    if not api_ok then error(tostring(api_failure), 0) end
    -- decoder and encoder must agree on known bit patterns before anything may be written
    for _, case in ipairs({ { 0x3F800000, 1.0 }, { 0x43AF0000, 350.0 }, { 0x42C80000, 100.0 },
                            { 0x3E800000, 0.25 }, { 0xBF000000, -0.5 }, { 0x44610000, 900.0 } }) do
        if bits_to_f32(case[1]) ~= case[2] or A.f32_bits(case[2]) ~= case[1] then
            error('float self-test failed', 0)
        end
    end
    if type(rawget(_G, 'update')) ~= 'function' then error('the game update hook is unavailable', 0) end
end)

if not ok then
    state.phase, state.failure = 'gave_up', tostring(failure)
    log('startup failed: ' .. tostring(failure))
    print('[' .. MOD.global .. '] ' .. tostring(failure))
    write_file(MOD.status, 'FAILED - ' .. tostring(failure) .. '\r\n' .. MOD.title .. ' v' .. MOD.version .. '\r\n')
    flush_log()
    return
end

log('armed; folder ' .. tostring(ensure_out_dir()))
write_file(MOD.status, 'WAITING - starting (nothing written yet)\r\n' .. MOD.title .. ' v' .. MOD.version .. '\r\n')
flush_log()

-- Guarded hook: we never cut other addons out of the update chain.
local original_update = update
local my_update
my_update = function(...)
    if not state.retired then
        local tick_ok, why = pcall(tick)
        if not tick_ok then
            state.errors = state.errors + 1
            log('tick: ' .. tostring(why))
            if state.errors >= 20 then state.retired = true end
        end
    end
    return original_update(...)
end
update = my_update
